  Path one=base.resolve("workshop/first"),two=base.resolve("workshop/second"),lua=base.resolve("workshop/lua"),unknown=base.resolve("workshop/unknown");text(one.resolve("42/mod.info"),"id=Viewpoint\n");text(two.resolve("common/mod.info"),"id=Viewpoint\n");text(lua.resolve("mod.info"),"id=Lua\n");text(unknown.resolve("mod.info"),"id=UnknownJava\njavaJarFile=x.jar\n");Path jar=text(one.resolve("payload.jar"),"same-bytes"),external=text(unknown.resolve("x.jar"),"same-bytes");
  String body="OZLLIVE1\n"+line("game",game.toString())+line("user",user.toString())+line("context",context.toString())+line("choices",choices.toString())+line("vanilla","false")+line("managed","Viewpoint")+line("selected","Viewpoint",one.toString())+line("jar",jar.toString(),"fixture.selected",sha(jar),"true");Path manifest=text(choices.resolve("live.manifest"),body);
  Method read=type.getDeclaredMethod("read",Path.class,String.class,Path.class);read.setAccessible(true);Object m=read.invoke(null,manifest,sha(manifest),game);Method filter=type.getDeclaredMethod("filter",List.class);filter.setAccessible(true);Method allow=type.getDeclaredMethod("allows",Path.class,String.class);allow.setAccessible(true);
  Method normalize=type.getDeclaredMethod("normalize",List.class);normalize.setAccessible(true);List<String> active=new ArrayList<String>(Arrays.asList("Lua","Other","Lua"));normalize.invoke(m,active);check(active.equals(Arrays.asList("Viewpoint","Lua","Other")),"enabled component merged into save choices with ordinary order retained and duplicates removed");
  text(manifest,body+line("component","Lua")+line("component","Viewpoint"));Object dependencies=read.invoke(null,manifest,sha(manifest),game);active=new ArrayList<String>(Arrays.asList("Other","Lua"));normalize.invoke(dependencies,active);check(active.equals(Arrays.asList("Other","Lua","Viewpoint")),"required ordinary dependency stays in relative ordinary order before selected component");
  text(manifest,body+line("override","true")+line("ordinary","Second")+line("ordinary","First"));Object override=read.invoke(null,manifest,sha(manifest),game);active=new ArrayList<String>(Arrays.asList("SaveOnly"));normalize.invoke(override,active);check(active.equals(Arrays.asList("Viewpoint","Second","First")),"explicit profile ordinary override is distinct from retaining save list");text(manifest,body);
  text(manifest,body+line("order","Lua")+line("order","Viewpoint")+line("order","Other"));Object anchored=read.invoke(null,manifest,sha(manifest),game);active=new ArrayList<String>(Arrays.asList("Lua","Other"));normalize.invoke(anchored,active);check(active.equals(Arrays.asList("Lua","Viewpoint","Other")),"loadAfter and loadBefore ordinary anchors preserve validated placement");normalize.invoke(anchored,active);check(active.equals(Arrays.asList("Lua","Viewpoint","Other")),"component merge is idempotent and does not reverse prepared defaults");text(manifest,body);
  List<String> roots=new ArrayList<String>(Arrays.asList(two.toString(),lua.toString(),one.toString(),unknown.toString()));filter.invoke(m,roots);check(roots.equals(Arrays.asList(lua.toString(),unknown.toString(),one.toString())),"explicit selected root replaces duplicate, ordinary Lua and unknown Java Lua retained");
  check((Boolean)allow.invoke(m,jar,"fixture.selected"),"exact selected path/package/current hash allowed");text(manifest,body.replace(line("jar",jar.toString(),"fixture.selected",sha(jar),"true"),line("jar",jar.toString(),"fixture.selected",sha(jar),"false")));Object denied=read.invoke(null,manifest,sha(manifest),game);check(!(Boolean)allow.invoke(denied,jar,"fixture.selected"),"explicit exact hash deny honored");text(manifest,body);check(!(Boolean)allow.invoke(m,external,"fixture.selected"),"identical external Java blocked");check(!(Boolean)allow.invoke(m,jar,"wrong.pkg"),"wrong package blocked");text(jar,"new current source");check(!(Boolean)allow.invoke(m,jar,"fixture.selected"),"changed live bytes need approval");
  text(lua.resolve("mod.info"),"id=Viewpoint\n");roots=new ArrayList<String>(Arrays.asList(lua.toString(),unknown.toString()));filter.invoke(m,roots);check(roots.equals(Arrays.asList(unknown.toString(),one.toString())),"discovery rechecks current root identity");
  text(manifest,body.replace(line("vanilla","false"),line("vanilla","true")).replace(line("selected","Viewpoint",one.toString()),"").replace(line("jar",jar.toString(),"fixture.selected",sha(external),"true"),""));Object vanilla=read.invoke(null,manifest,sha(manifest),game);roots=new ArrayList<String>(Arrays.asList(two.toString(),unknown.toString()));filter.invoke(vanilla,roots);check(roots.isEmpty(),"vanilla has zero roots");
  Path bridge=context.resolve("bridge");text(bridge.resolve("42/mod.info"),"id=OrangeLauncherSession\n");String vanillaBody=new String(Files.readAllBytes(manifest),StandardCharsets.UTF_8);text(manifest,vanillaBody+line("managed","OrangeLauncherSession")+line("selected","OrangeLauncherSession",bridge.toString()));Object bridged=read.invoke(null,manifest,sha(manifest),game);roots=new ArrayList<String>();filter.invoke(bridged,roots);active=new ArrayList<String>(Arrays.asList("Lua","Viewpoint"));normalize.invoke(bridged,active);check(roots.equals(Arrays.asList(bridge.toString()))&&active.equals(Arrays.asList("OrangeLauncherSession")),"vanilla target exposes only owned explicit bridge");
  Method client=type.getDeclaredMethod("mergeClient",List.class);client.setAccessible(true);active=new ArrayList<String>(Arrays.asList("ServerB","ServerA","Disabled"));client.invoke(override,active);check(active.equals(Arrays.asList("ServerB","ServerA","Disabled","Viewpoint")),"network order and IDs remain exact; named ordinary list never replaces server list");
  Class<?> selectionType=Class.forName("ozl.environment.LiveActiveSelection");Constructor<?> ctor=selectionType.getDeclaredConstructor(type);ctor.setAccessible(true);Object selection=ctor.newInstance(override);Method defaultLoaded=selectionType.getDeclaredMethod("defaultLoaded",List.class);defaultLoaded.setAccessible(true);List<String> defaults=new ArrayList<String>(Arrays.asList("GameEdited","Second"));defaultLoaded.invoke(selection,defaults);check(defaults.equals(Arrays.asList("Viewpoint","GameEdited","Second")),"completed default read retains session edits rather than resetting named ordinary choices");
  Method copied=selectionType.getDeclaredMethod("copied",Object.class,Object.class,String.class,List.class,boolean.class);copied.setAccessible(true);Object inspected=new Object(),current=new Object();List<String> currentIds=new ArrayList<String>(Arrays.asList("SaveOnly"));copied.invoke(selection,current,inspected,"currentGame",currentIds,false);check(currentIds.equals(defaults),"currentGame gets named ordinary list before raw-field loaded bookkeeping");List<String> settings=new ArrayList<String>(Arrays.asList("ServerSetting"));copied.invoke(selection,new Object(),inspected,"serversettings",settings,false);check(settings.equals(Arrays.asList("ServerSetting")),"server settings remain unchanged");
  Method readSource=selectionType.getDeclaredMethod("readSource",String.class,Object.class);readSource.setAccessible(true);Path original=text(user.resolve("Saves/Sandbox/Original/mods.txt"),"source-save-metadata");readSource.invoke(selection,original.toString(),inspected);copied.invoke(selection,current,inspected,"currentGame",currentIds,false);Method output=selectionType.getDeclaredMethod("writePath",String.class,Object.class,String.class);output.setAccessible(true);Path redirected=Paths.get((String)output.invoke(selection,original.toString(),current,"currentGame"));check(redirected.startsWith(choices)&&!redirected.equals(original),"only captured currentGame save metadata redirects into own session");check(output.invoke(selection,user.resolve("mods/default.txt").toString(),new Object(),"default").equals(user.resolve("mods/default.txt").toString()),"native owned default persistence is not suppressed");check(readSource!=null&&new String(Files.readAllBytes(original),StandardCharsets.UTF_8).equals("source-save-metadata"),"original save metadata unchanged by routing");
  if(args.length>1){Class<?> contract=Class.forName("ozl.environment.LiveTargetContract");Method verify=contract.getDeclaredMethod("verifyJar",Path.class);verify.setAccessible(true);verify.invoke(null,Paths.get(args[1]));check(true,"actual installed bytecode supports scoped live phase boundaries (no game initialized)");}
  System.out.println("PASS "+checks+" live manifest assertions");
